function t(k){return (words[lang]&&words[lang][k])||words.en[k]||k;}
function esc(v){return String(v==null?"":v).replace(/[&<>"']/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c];});}
function fmtDate(v){if(!v)return "—";var d=new Date(v);return isNaN(d.getTime())?"—":new Intl.DateTimeFormat(lang==="ar"?"ar":"en-GB",{dateStyle:"medium"}).format(d);}function fmtDateTime(v){if(!v)return "—";var d=new Date(v);return isNaN(d.getTime())?"—":new Intl.DateTimeFormat(lang==="ar"?"ar":"en-GB",{dateStyle:"medium",timeStyle:"short"}).format(d);}
