function bindGlobalSearch(){
 var input=$("globalSearch"),box=$("globalSearchResults"),timer=null,sequence=0;
 if(!input||!box)return;
 function close(){box.hidden=true;input.setAttribute("aria-expanded","false");}
 async function search(query){
  var q=String(query||"").trim(),run=++sequence;
  if(q.length<2){close();box.innerHTML="";return;}
  box.hidden=false;input.setAttribute("aria-expanded","true");
  box.innerHTML='<div class="global-search-state">'+(lang==="ar"?"جارٍ البحث…":"Searching…")+'</div>';
  var jobs=[];
  if(has("users:read"))jobs.push({type:"users",label:lang==="ar"?"مستخدمون":"Users",promise:api("/admin/users?page=1&page_size=5&search="+encodeURIComponent(q))});
  if(has("services:read"))jobs.push({type:"services",label:lang==="ar"?"خدمات":"Services",promise:api("/admin/services?page=1&page_size=5&search="+encodeURIComponent(q))});
  if(has("requests:read"))jobs.push({type:"requests",label:lang==="ar"?"طلبات":"Requests",promise:api("/admin/requests?page=1&page_size=5&search="+encodeURIComponent(q))});
  if(!jobs.length){box.innerHTML='<div class="global-search-state">'+t("noPermission")+'</div>';return;}
  var settled=await Promise.allSettled(jobs.map(function(job){return job.promise;}));
  if(run!==sequence)return;
  var rows=[];
  settled.forEach(function(result,index){
   if(result.status!=="fulfilled")return;
   var job=jobs[index],items=result.value.items||[];
   items.slice(0,5).forEach(function(item){
    var title=job.type==="users"?personName(item):job.type==="services"?item.name:item.title;
    var subtitle=job.type==="users"?(item.username||item.email||""):job.type==="services"?(item.short_description||item.description||""):statusLabel(item.status);
    rows.push({type:job.type,title:title||q,subtitle:subtitle,label:job.label,query:q});
   });
  });
  if(!rows.length){box.innerHTML='<div class="global-search-state">'+(lang==="ar"?"لا توجد نتائج متاحة":"No accessible results")+'</div>';return;}
  box.innerHTML=rows.map(function(row){return '<button type="button" class="global-search-result" role="option" data-search-type="'+esc(row.type)+'" data-search-query="'+esc(row.query)+'"><span class="global-search-result-main"><b>'+esc(row.title)+'</b><small>'+esc(row.subtitle)+'</small></span><span class="global-search-result-type">'+esc(row.label)+'</span></button>';}).join("");
 }
 input.addEventListener("input",function(){sequence++;clearTimeout(timer);if(input.value.trim().length<2){close();box.innerHTML="";return;}box.hidden=false;input.setAttribute("aria-expanded","true");box.innerHTML='<div class="global-search-state">'+(lang==="ar"?"جارٍ البحث…":"Searching…")+'</div>';timer=setTimeout(function(){search(input.value);},280);});
 input.addEventListener("keydown",function(event){if(event.key==="Escape"){close();input.blur();}if(event.key==="Enter"){var first=box.querySelector("[data-search-type]");if(first)first.click();}});
 box.addEventListener("click",function(event){
  var result=event.target.closest&&event.target.closest("[data-search-type]");if(!result)return;
  var q=result.dataset.searchQuery||input.value,type=result.dataset.searchType;
  close();input.value="";
  if(type==="users"){$("userSearch").value=q;openPage("users");}
  else if(type==="services"){$("serviceSearch").value=q;openPage("services");}
  else if(type==="requests"){$("requestSearch").value=q;openPage("requests");}
 });
 document.addEventListener("click",function(event){if(!event.target.closest(".global-search-wrap"))close();});
}
